head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 editFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 editFormat 을 설정할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Row 가 MultiLine 이어도 모든 Column 은 고유한 인덱스를 가집니다.",
        "Body Column 이 inputType='text' 인 경우에 동작합니다.",
        "editFormat(필수) 파라미터로 입력/표시 시 적용할 포맷 마스크를 설정합니다.",
        "editFormat 의 '#' 마스크 문자는 0~9 의 숫자만 입력할 수 있습니다.",
        "editFormat 의 'A' 마스크 문자는 A~Z 의 대문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 'a' 마스크 문자는 a~z 의 소문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 'Z' 마스크 문자는 0~9 의 숫자와 A~Z 의 대문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 'z' 마스크 문자는 0~9 의 숫자와 a~z 의 소문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 'S' 마스크 문자는 a~z, A~Z 의 대/소문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 'X','9' 마스크 문자는 0~9 의 숫자와 a~z, A~Z 의 대/소문자 알파벳만 입력할 수 있습니다.",
        "editFormat 의 '*' 마스크 문자는 0~9, a~z, A~Z, 그리고 ~!@#$%^&*()_+|-=\\{}[]:\";'<>?,./ 의 특수문자를 입력할 수 있습니다.",
        "editFormat 의 'K' 마스크 문자는 모든 한글만 입력할 수 있으며 다른 마스크 문자와 함께 사용할 수 없습니다.",
        "editFormat 의 '||' 기호는 한 개 이상의 포맷을 정의할 때 포맷의 구분자로 사용합니다.",
        "editFormat 의 '{,}' 기호는 특정 범위(여러개 가능)의 입력 문자를 editDisplayChar 속성값으로 마스킹 처리합니다.",
        "editFormat 의 '!' 기호는 마스크 문자와 특수 기호를 이스케이프 처리합니다.",
        "입력 문자가 마스크 문자와 맞지 않으면 입력되지 않습니다.",
        "maxlength 속성과 함께 사용하면 native maxlength 가 먼저 적용되어 editFormat 이 입력 길이를 제어하지 못하므로 함께 사용하지 않는 것을 권장합니다.",
        "복수포맷('||') 설정 시 editPlaceholderChar 속성이 설정되어 있으면 마스크 문자 갯수가 가장 많은 포맷 하나만 사용됩니다.",
        "복수포맷('||') 설정 시 editPlaceholderChar 속성이 미설정이면 입력 길이에 따라 포맷이 자동으로 선택됩니다.",
        "설정된 포맷과 맞지 않는 Cell 값은 제거됩니다.",
    ]
}



// columnInfo(컬럼 인덱스) 별 권장 editFormat (par_editFormat 자동 선택용)
//  0:cAlnum(text·동작) / 1:cHide(text·숨김) / 2:cCustom(custom·미동작) / 3:cPhone(text·복수포맷) / 4:cPhonePH(text·editPlaceholderChar) / 5:cMax(text·maxlength)
scwin.colEditFormatMap = {
    "0": "####/##/##",
    "1": "####/##/##",
    "2": "####/##/##",
    "3": "###-###-####||####-####",
    "4": "###-###-####||####-####",
    "5": "####/##/##"
};

// columnInfo 선택이 바뀌면 해당 컬럼 권장 editFormat 을 par_editFormat 에 자동 선택
scwin.par_columnInfo_onchange = function () {
    let col = par_columnInfo.getValue();
    let fmt = scwin.colEditFormatMap[col];
    if (typeof fmt !== 'undefined') {
        par_editFormat.setValue(fmt);
    }
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 columnInfo 선택값(0)에 맞는 editFormat 자동 선택
    par_columnInfo.setValue("0");
    scwin.par_columnInfo_onchange();
};



// comp 생성 : text(동작)/text(숨김)/custom(미동작)/text(복수포맷)/text(editPlaceholderChar)/text(maxlength) Column 구성
//  setColumnEditFormat 은 inputType='text' 인 Column 에서만 동작 (custom 은 미동작)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column(숨김 포함) 0:cAlnum(text/동작·editDisplayChar=*) / 1:cHide(text/숨김) / 2:cCustom(custom/미동작) / 3:cPhone(text/복수포맷) / 4:cPhonePH(text/editPlaceholderChar=_) / 5:cMax(text/maxlength=5), 데이터 3행.\n[절차] columnInfo(인덱스)·editFormat(마스크) 선택 후 (setColumnEditFormat 실행). text 컬럼 셀을 더블클릭 편집하고 마스크에 맞는/안맞는 문자를 입력한 뒤 포커스아웃하면 편집값·표시값이 자동 출력됨.\n[확인] text 컬럼만 동작(2:cCustom 미동작). 적용 즉시 컬럼이 다시 렌더되어 기존값이 마스크로 표시되며, 마스크와 안맞는 값은 제거됨. 마스크별 허용문자(#숫자 A대문자 a소문자 Z숫자+대문자 등) 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cAlnum" name="cAlnum" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cHide" name="cHide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cCustom" name="cCustom" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cPhone" name="cPhone" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cPhonePH" name="cPhonePH" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cMax" name="cMax" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "cAlnum": "20250115", "cHide": "20250115", "cCustom": "20250115", "cPhone": "12341234",   "cPhonePH": "0101234567", "cMax": "1234567890" },
        { "cAlnum": "20251231", "cHide": "20251231", "cCustom": "20251231", "cPhone": "0212341234", "cPhonePH": "0212341234", "cMax": "9876543210" },
        { "cAlnum": "20250707", "cHide": "20250707", "cCustom": "20250707", "cPhone": "0311239876", "cPhonePH": "0311239876", "cMax": "5550001111" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text/text(숨김)/custom/text/text/text Column)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:740px;height:230px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnEditFormat 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" inputType="text" id="h0" value="0:text(동작)"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h1" value="1:text(숨김)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h2" value="2:custom(미동작)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h3" value="3:text(복수포맷)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h4" value="4:text(editPlaceholderChar)"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h5" value="5:text(maxlength=5)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 0 : text -> setColumnEditFormat 동작 대상. editDisplayChar='*' 로 '{,}' 마스킹 데모
    strTarget += '<w2:column width="140" inputType="text" dataType="text" editDisplayChar="*" id="cAlnum" dataList="cAlnum"></w2:column>';
    // 1 : text 숨김(setColumnVisible(1,false)) -> 숨김 Column 포함 인덱스 검증용
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="cHide" dataList="cHide"></w2:column>';
    // 2 : custom -> 전제 미충족(inputType=custom) -> 미동작
    strTarget += '<w2:column width="130" inputType="custom" dataType="text" id="cCustom" dataList="cCustom"></w2:column>';
    // 3 : text -> 복수포맷('||') 입력길이별 자동선택 (editPlaceholderChar 미설정)
    strTarget += '<w2:column width="150" inputType="text" dataType="text" id="cPhone" dataList="cPhone"></w2:column>';
    // 4 : text + editPlaceholderChar='_' -> 복수포맷('||') 시 가장 긴 포맷 하나만 사용
    strTarget += '<w2:column width="150" inputType="text" dataType="text" editPlaceholderChar="_" id="cPhonePH" dataList="cPhonePH"></w2:column>';
    // 5 : text + maxlength=5 -> native maxlength 가 먼저 적용되어 editFormat 입력길이 제어 불가
    strTarget += '<w2:column width="100" inputType="text" dataType="text" maxlength="5" id="cMax" dataList="cMax"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(cHide, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// [실행] setColumnEditFormat : columnInfo(인덱스) + editFormat 마스크로 해당 Column 의 editFormat 속성을 설정한다.
//  - 호출 직후 : 설정된 editFormat 속성값 + 화면 표시값(즉시 재렌더·재마스킹 결과) 확인
//    (text 컬럼만 동작, custom 컬럼은 editFormat 속성이 설정되지 않아 '(미설정)' 으로 출력됨)
scwin.btn_setColumnEditFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let editFormat = par_editFormat.getValue();
    let colID = target1.getColumnID(columnInfo);

    target1.setColumnEditFormat(columnInfo, editFormat);

    // 설정 후 해당 Column 의 editFormat 속성값 / inputType 확인 (getCellInfo().options)
    let cellInfo = target1.getCellInfo(columnInfo);
    let opts = (cellInfo && cellInfo.options) ? cellInfo.options : {};
    let setFmt = (typeof opts.editFormat !== 'undefined' && opts.editFormat !== '') ? opts.editFormat : '(미설정)';
    let inputType = opts.inputType || '';

    // 호출 직후 화면 표시값(editFormat 재렌더·재마스킹 반영) 수집
    let arr = scwin.collectColText(columnInfo);

    let msg = "setColumnEditFormat(" + columnInfo + ", '" + editFormat + "') [" + colID + ", inputType=" + inputType + "]";
    msg += "\n[적용 editFormat 속성] '" + setFmt + "'";
    msg += "\n[표시값(재렌더)] " + arr.join(', ');

    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// 해당 Column 의 모든 Row 화면 표시값(td.textContent) 수집
scwin.collectColText = function (columnInfo) {
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
        arr.push(td ? td.textContent.trim() : '');
    }
    return arr;
}

// [이벤트] 셀을 직접 편집 -> 포커스 아웃(onafteredit) 하는 실제 인터랙션마다
//  편집 상태에서의 값(editFormat 적용)과 포커스아웃 이후 표시 상태 값을 자동 출력한다.
//  editFormat 은 applyFormat=all 로 동작하여 편집값/표시값에 동일 포맷이 적용된다.
//  - onbeforeedit(row, col, value) : 편집모드 진입 직전. value = 편집 입력창에 표시되는 값
scwin.target1_onbeforeedit = function (row, col, value) {
    scwin._editValue = value;
};

//  - onafteredit(row, col, value) : 셀 편집이 끝나 포커스가 빠져나온 직후 발생.
//    (주의) onafteredit 의 value 파라미터 = 마스크 미적용 Cell 원본값(getCellData 와 동일). editFormat 으로
//     표시되던 편집 상태 값이 아니므로, 편집 입력창(공용 에디터 input, id=G_...target1__<colID>)의 value 를
//     읽어 마스크(editFormat) 적용된 편집 상태 값을 캡처한다. (편집값) 과 (표시값) 은 applyFormat=all 로 동일 마스크가 적용된다.
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    // 편집 입력창에 editFormat 으로 표시되던 마스크 적용값 (없으면 raw value 로 폴백)
    let editor = document.querySelector("input[id^='G_'][id$='target1__" + colID + "']");
    let editVal = editor ? editor.value : value;
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';

    let msg = "편집->포커스아웃 [" + colID + "] (" + row + "," + col + ")";
    msg += "\n[편집값(editFormat)] " + editVal;
    msg += "\n[표시값] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
